mapper.delete:
delete
from corgi_activity_attender
where user_id = #{userSignUp.userId}
  and activity_id = #{userSignUp.activityId}

mapper.update:
update corgi_activity_attender
set `status` = #{userSignUp.status}
where user_id = #{userSignUp.userId}
  and activity_id = #{userSignUp.activityId}

mapper.select:
select `status`
from corgi_activity_attender
where user_id = #{userId}
  and activity_id = #{activityId}

select a.user_id userId, d.avatar avatar, d.avatar_check_status avatarCheckStatus, d.nickname `nickname` from corgi_activity_attender a left join corgi_user_detail d on d.user_id = a.user_id left join corgi_user_follow f on f.follow_user_id = a.user_id where a.activity_id = #{activityId}
and a.`status` = #{status}
group by a.user_id,d.nickname order by count(f.user_id) DESC limit 3

select
count(1)
from corgi_activity_attender a
where a.activity_id = #{activityId}

    and a.`status` = #{status}

select distinct activity_id
from corgi_activity_creator c
left join corgi_user_follow f on f.follow_user_id = c.creator_id
where c.check_status != 'fail'
and (c.creator_id = #{query.userId}
or f.user_id = #{query.userId})

    and c.activity_id < #{query.activityId}


    and c.category = #{query.category}

order by c.id desc limit #{query.pageSize}

select c.activity_id id, c.ctime createTime
from corgi_activity_creator c
where c.check_status != 'fail'
and c.creator = #{query.userId}
  and c.ctime < #{query.endTime}
order by c.id desc limit #{query.pageSize}

select activity_id
from corgi_activity_attender
where user_id = #{userId}
order by update_time desc
    limit #{start}, #{size}

select c.activity_id from corgi_activity_creator c
left join corgi_activity_like l on c.activity_id = l.activity_id

    join corgi_activity_topic t on t.activity_id = c.activity_id and t.topic = #{topic}

where c.category in ('${category}')

    and c.ctime >= #{date}

group by c.activity_id
order by count(l.id) desc
limit #{start},#{size}

mapper.update:
update corgi_activity_creator
set check_status = #{status}
where activity_id = #{activityId}

mapper.select:
select a.activity_id
from (
         select activity_id, ctime
         from corgi_activity_creator
         where creator_id = #{userId}
           and category = 'activity'
         union
         select activity_id, update_time ctime
         from corgi_activity_attender
         where user_id = #{userId}
           and status = '1') a
order by a.ctime desc
    limit #{start}, #{size}
